44	func newFactsRetractCommand(opts Options) *cobra.Command {
45		var (
46			jsonOut bool
47			global  bool
48		)
49		cmd := &cobra.Command{
50			Use:   "retract <memory-id>",
51			Short: "Mark a memory as retracted (no longer true); pruned later by gc",
52			Args:  cobra.ExactArgs(1),
53			RunE: func(cmd *cobra.Command, args []string) error {
54				factID := args[0]
55				var (
56					brainDir string
57					err      error
58				)
59				// A fact that can be written and not retracted is a fact you are
60				// stuck with. Global facts surface in every repository, so being
61				// stuck with a wrong one is worse, not better.
62				if global {
63					brainDir, err = factstore.ResolveGlobalTarget(opts.Env)
64				} else {
65					_, brainDir, _, err = resolveFactsTarget(cmd.Context(), opts, agentSurfaceTarget(opts, nil), "")
66				}
67				if err != nil {
68					return err
69				}
70				now := opts.Now().UTC()
71				changed := false
72				// Seeded with the id so the event is still identifiable if the
73				// record cannot be re-read after the mutation.
74				retracted := factRecord{ID: factID}
75				if err := brainstore.WithBrainWriteLockContext(cmd.Context(), brainDir, func() error {
76					if _, err := migrateFactStoreLocked(brainDir); err != nil {
77						return err
78					}
79					facts, err := factstore.Load(brainDir)
80					if err != nil {
81						return err
82					}
83					found, didChange := retractFact(facts, factID, now)
84					if !found {
85						if global {
86							return fmt.Errorf("no global memory %s", factID)
87						}
88						return fmt.Errorf("no memory %s", factID)
89					}
90					changed = didChange
91					if !changed {
92						return nil
93					}
94					// Captured under the lock so the webhook reports the kind and
95					// paths of the fact that was actually retracted, rather than an
96					// id a subscriber would have to look up through an API that only
97					// listens on loopback.
98					if i := indexOfFact(facts, factID); i >= 0 {
99						retracted = facts[i]
100					}
101					if err := factstore.Write(brainDir, facts); err != nil {
102						return err
103					}
104					return updateFactSourceManifestLocked(brainDir, now)
105				}); err != nil {
106					return err
107				}
108				// Only on a real transition: re-retracting an already-retracted fact
109				// changed nothing, and a subscriber that fired on it would act on
110				// news that is not news.
111				if changed {
112					if global {
113						webhook.NotifyGlobalFactWebhook(cmd.Context(), cmd.ErrOrStderr(), webhook.WebhookFactRetracted, retracted, now)
114					} else {
115						webhook.NotifyFactWebhook(cmd.Context(), cmd.ErrOrStderr(), opts, webhook.WebhookFactRetracted, retracted.Branch, retracted, now)
116					}
117				}
118				if jsonOut {
119					return cmdutil.WriteJSON(cmd, map[string]any{"id": factID, "status": factStatusRetracted, "changed": changed})
120				}
121				where := "in this repository"
122				if global {
123					where = "globally"
124				}
125				if changed {
126					fmt.Fprintf(cmd.OutOrStdout(), "retracted %s %s (run `memories gc --force` to prune)\n", factID, where)
127				} else {
128					fmt.Fprintf(cmd.OutOrStdout(), "%s %s was already retracted\n", factID, where)
129				}
130				return nil
131			},
132		}
133		cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit the result as JSON")
134		cmd.Flags().BoolVar(&global, "global", false, "Retract a global memory rather than one of this repository's")
135		return cmd
136	}
