140	func newFactsGCCommand(opts Options) *cobra.Command {
141		var (
142			branch  string
143			force   bool
144			retain  time.Duration
145			jsonOut bool
146			global  bool
147		)
148		cmd := &cobra.Command{
149			Use:   "gc",
150			Short: "Prune retracted and old superseded memories; report orphans",
151			Args:  cobra.NoArgs,
152			RunE: func(cmd *cobra.Command, args []string) error {
153				var (
154					brainDir       string
155					resolvedBranch string
156					err            error
157				)
158				// Without this the global store is write-only in one direction:
159				// facts can be retracted there and never pruned, so it grows
160				// without bound and the documented promise that global facts get
161				// the same lifecycle as repository ones is not kept.
162				if global {
163					if strings.TrimSpace(branch) != "" {
164						return fmt.Errorf("--global and --branch cannot be combined: a global memory is not on a branch")
165					}
166					brainDir, err = factstore.ResolveGlobalTarget(opts.Env)
167				} else {
168					_, brainDir, _, err = resolveFactsTarget(cmd.Context(), opts, agentSurfaceTarget(opts, nil), "")
169				}
170				if err != nil {
171					return err
172				}
173				resolvedBranch = strings.TrimSpace(branch)
174				return runFactsGC(cmd, opts, brainDir, resolvedBranch, force, retain, jsonOut)
175			},
176		}
177		cmd.Flags().BoolVar(&global, "global", false, "Prune the global memory store rather than this repository's")
178		cmd.Flags().StringVar(&branch, "branch", "", "Only gc memories stamped with this branch (default: all)")
179		cmd.Flags().BoolVar(&force, "force", false, "Actually prune (default: dry-run reporting what would be pruned)")
180		cmd.Flags().DurationVar(&retain, "retain", defaultFactRetention, "Retain superseded memories updated within this window")
181		cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit the gc summary as JSON")
182		return cmd
183	}
