208	func runFactsReclassify(cmd *cobra.Command, opts Options, brainDir string, force, jsonOut bool) error {
209		now := opts.Now().UTC()
210		var facts []factRecord
211		changed := 0
212		// The whole load-mutate-write runs under the brain write lock, like every
213		// other fact mutator (remember, retract, gc, distill's flush) and like the
214		// refresh-time reclassifyAllFacts. Reading the store outside it and
215		// writing the mutated copy back is a lost update: a concurrent writer that
216		// commits between this read and this write is silently overwritten, and
217		// its facts disappear.
218		if err := brainstore.WithBrainWriteLockContext(cmd.Context(), brainDir, func() error {
219			if _, err := migrateFactStoreLocked(brainDir); err != nil {
220				return err
221			}
222			loaded, err := factstore.Load(brainDir)
223			if err != nil {
224				return err
225			}
226			facts = loaded
227			changed = factstore.Reclassify(facts, force)
228			if changed > 0 {
229				if err := factstore.Write(brainDir, facts); err != nil {
230					return err
231				}
232			}
233			// Always refresh the manifest, even on a no-op reclassify: a store predating
234			// the by_kind field has valid kinds but a stale/absent histogram that only a
235			// manifest rebuild repairs.
236			return updateFactSourceManifestLocked(brainDir, now)
237		}); err != nil {
238			return err
239		}
240		byKind := map[string]int{}
241		for _, f := range facts {
242			if f.Status == factStatusActive {
243				byKind[factstore.KindOrInferred(f)]++
244			}
245		}
246		if jsonOut {
247			return cmdutil.WriteJSON(cmd, map[string]any{"changed": changed, "facts": len(facts), "by_kind": byKind})
248		}
249		fmt.Fprintf(cmd.OutOrStdout(), "reclassified %d of %d memory(ies)\n", changed, len(facts))
250		for _, kind := range []string{factKindDecision, factKindInvariant, factKindGotcha, factKindPreference, factKindConvention} {
251			if byKind[kind] > 0 {
252				fmt.Fprintf(cmd.OutOrStdout(), "  %-11s %d\n", kind, byKind[kind])
253			}
254		}
255		return nil
256	}
