310	func newFactsMapCommand(opts Options) *cobra.Command {
311		var (
312			path    string
313			depth   int
314			jsonOut bool
315		)
316		cmd := &cobra.Command{
317			Use:   "map",
318			Short: "Render the synthesized memory outline (summaries + structure) with progressive disclosure",
319			Args:  cobra.NoArgs,
320			RunE: func(cmd *cobra.Command, args []string) error {
321				_, brainDir, _, err := resolveFactsTarget(cmd.Context(), opts, agentSurfaceTarget(opts, nil), "")
322				if err != nil {
323					return err
324				}
325				// Always rebuild the structure from the live facts (it is deterministic
326				// and never stale), then overlay stored summaries only where the node's
327				// fingerprint still matches — so a summary for a changed subtree is
328				// hidden rather than shown stale, and no `facts outline` run is required
329				// to see the map.
330				facts, err := factstore.Load(brainDir)
331				if err != nil {
332					return err
333				}
334				outline := buildFactOutlineTree(facts, opts.Now().UTC())
335				if stored, storedErr := loadFactOutline(brainDir); storedErr == nil {
336					for key, n := range outline.Nodes {
337						if s, ok := stored.Nodes[key]; ok && s.Fingerprint == n.Fingerprint && s.Summary != "" {
338							n.Summary = s.Summary
339							outline.Nodes[key] = n
340						}
341					}
342				}
343				node := path
344				if _, ok := outline.Nodes[node]; !ok {
345					return fmt.Errorf("no outline node %q", path)
346				}
347				// The outline counts what factstore.Load produced. When the manifest
348				// declares more than that, "root (4 facts)" is a count of survivors
349				// rendered as if it were the corpus. Qualify it before rendering,
350				// and exit nonzero so a caller cannot read the map as complete.
351				integrityErr := reportFactStoreIntegrity(cmd, brainDir, jsonOut)
352				if jsonOut {
353					if err := cmdutil.WriteJSON(cmd, outline); err != nil {
354						return err
355					}
356					return integrityErr
