374	// runFactsGC prunes over the flat store. branch is an explicit metadata
375	// filter: when set, only records stamped with that branch are gc candidates
376	// and everything else passes through untouched; empty means the whole store.
377	func runFactsGC(cmd *cobra.Command, opts Options, brainDir, branch string, force bool, retain time.Duration, jsonOut bool) error {
378		now := opts.Now().UTC()
379		gcPass := func(facts []factRecord) ([]factRecord, gcResult, error) {
380			taxonomy, err := factstore.LoadTaxonomy(brainDir, now)
381			if err != nil {
382				return nil, gcResult{}, err
383			}
384			scoped := facts
385			var passthrough []factRecord
386			if branch != "" {
387				scoped = scoped[:0:0]
388				for _, f := range facts {
389					if f.Branch == branch {
390						scoped = append(scoped, f)
391					} else {
392						passthrough = append(passthrough, f)
393					}
394				}
395			}
396			result := gcFacts(scoped, taxonomy, now, retain)
397			return append(passthrough, result.Kept...), result, nil
398		}
399		facts, err := factstore.Load(brainDir)
400		if err != nil {
401			return err
402		}
403		_, result, err := gcPass(facts)
404		if err != nil {
405			return err
406		}
407		summary := map[string]any{
408			"branch":    branch,
409			"pruned":    len(result.Pruned),
410			"orphans":   len(result.Orphans),
411			"remaining": len(result.Kept),
412			"applied":   force,
413		}
414		if force {
415			if err := brainstore.WithBrainWriteLockContext(cmd.Context(), brainDir, func() error {
416				if _, err := migrateFactStoreLocked(brainDir); err != nil {
417					return err
418				}
419				facts, err := factstore.Load(brainDir)
420				if err != nil {
421					return err
422				}
423				kept, res, err := gcPass(facts)
424				if err != nil {
425					return err
426				}
427				result = res
428				summary["pruned"] = len(result.Pruned)
429				summary["orphans"] = len(result.Orphans)
430				summary["remaining"] = len(result.Kept)
431				if err := factstore.Write(brainDir, kept); err != nil {
432					return err
433				}
434				return updateFactSourceManifestLocked(brainDir, now)
435			}); err != nil {
436				return err
437			}
438		}
439		if jsonOut {
440			return cmdutil.WriteJSON(cmd, summary)
441		}
442		verb := "would prune"
443		if force {
444			verb = "pruned"
445		}
446		scope := "in this repository"
447		if branch != "" {
448			scope = "stamped " + branch
449		}
450		fmt.Fprintf(cmd.OutOrStdout(), "%s %d memory(ies) %s (%d retracted/old-superseded); %d taxonomy-orphaned memory(ies) reported (kept); %d remaining\n",
451			verb, len(result.Pruned), scope, len(result.Pruned), len(result.Orphans), len(result.Kept))
452		if !force && len(result.Pruned) > 0 {
453			fmt.Fprintln(cmd.OutOrStdout(), "re-run with --force to apply")
454		}
455		return nil
456	}
