190		// machine surface whose reason for hiding is recorded at its registration
191		// in root.go and still holds; the documents that name them address that
192		// audience, not a new user. Adding to this list is how a decision to keep
193		// something hidden gets written down -- a new hidden-but-documented command
194		// fails this test until somebody does.
195		hiddenOnPurpose := map[string]string{
196			"review":           "machine contract for the host CLI's `entire review`, not a human verb",
197			"history-eval":     "measurement harness for the retrieval layer; developer tooling",
198			"history-eval-gen": "measurement harness for the retrieval layer; developer tooling",
199			"bench":            "maintainer-only measurement harness, explicitly introduced as such in getting-started",
